fn tri_local(n: i32, span: i32) -> i32 {
    let m: i32 = n % (span * 2);
    if m > span { span * 2 - m } else { m }
}

fn frame(t: i32) {
    host::display::clear(0x0c0c10);
    if host::display::state_get(0) == 0 {
        host::display::state_set(0, 1);
        host::display::state_set(1, host::compose::spawn_lib("lib-trig"));
    }
    let h: i32 = host::display::state_get(1);
    let st: i32 = host::compose::status(h);
    let x: i32 = 20 + (t * 3) % 460;
    let mut y: i32 = 240;
    if st == 1 {
        let s: i32 = host::compose::call(h, "sin256", t * 4, 0, 0, 0);
        if host::compose::call_ok() == 0 {
            y = 240 - s * 120 / 256;
            host::display::draw_string(8, 8, "WAVE: LIB-TRIG", 0x00ff66, 1);
        } else {
            y = 180 + tri_local(t * 4, 120);
            host::display::draw_string(8, 8, "WAVE: LOCAL FALLBACK", 0xffff00, 1);
        }
    } else {
        if st == 2 {
            y = 180 + tri_local(t * 4, 120);
            host::display::draw_string(8, 8, "LIB FAILED - LOCAL TRIANGLE", 0xffff00, 1);
        } else {
            host::display::draw_string(8, 8, "MOUNTING LIB-TRIG...", 0x808080, 1);
        }
    }
    host::display::fill_rect(x, y - 8, 16, 16, 0x40c0ff);
    host::display::present();
}
